/* Browser-local research prototype. No accounts, entries, consent or rewards are sent to a service. */
'use strict';
const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={arrow:'M4 10h12m-5-5 5 5-5 5',back:'M16 10H4m5-5-5 5 5 5',heart:'M17 4c-2-2-5-1-7 1C8 3 5 2 3 4c-4 4 3 9 7 12 4-3 11-8 7-12Z',search:'M14 14l4 4M15 8A7 7 0 1 1 1 8a7 7 0 0 1 14 0',clock:'M10 5v5l3 2M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',check:'m4 10 4 4 8-8',user:'M16 18v-2a6 6 0 0 0-12 0v2M13 5a3 3 0 1 1-6 0 3 3 0 0 1 6 0',ticket:'M2 4h16v4a2 2 0 0 0 0 4v4H2v-4a2 2 0 0 0 0-4V4Zm11 0v3m0 3v1m0 3v2',gift:'M2 7h16v4H2V7Zm2 4v7h12v-7M10 7v11M10 7C2 7 4 0 8 3l2 4Zm0 0c8 0 6-7 2-4l-2 4Z',globe:'M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0ZM2 10h16M10 2c-4 4-4 12 0 16 4-4 4-12 0-16',menu:'M3 5h14M3 10h14M3 15h14',close:'m4 4 12 12M16 4 4 16',info:'M10 9v5m0-9v1M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',pin:'M15 7c0 4-5 10-5 10S5 11 5 7a5 5 0 0 1 10 0ZM12 7a2 2 0 1 1-4 0 2 2 0 0 1 4 0'};
const icon=(n)=>`<svg class="icon" aria-hidden="true" viewBox="0 0 20 20"><path d="${paths[n]||paths.info}"/></svg>`;
const offers=[
 {id:'game-night',brand:'Doritos',title:'Your next game night, upgraded.',prize:'A PlayStation®5 console',type:'Prize draw',art:'console',status:'Active',end:'2026-11-08',countries:['United Kingdom','France','Germany'],requirement:'One code from an eligible pack',short:'Pack code required',description:'Make your next night in a big one. Explore this example prize draw for a PlayStation®5 console.',step:'Enter the example pack code',code:true},
 {id:'live-music',brand:'Pepsi',title:'Good music. Even better company.',prize:'A pair of live music tickets',type:'Prize draw',art:'music',status:'Ending soon',end:'2026-10-18',countries:['United Kingdom','Germany'],requirement:'A free online entry',short:'No purchase required',description:'Your favourite kind of night, with someone you love. Try a free entry for two tickets in this illustrative promotion.',step:'Confirm your example entry',code:false},
 {id:'instant-break',brand:'Rockstar',title:'A little win for your next break.',prize:'A £10 digital gift card',type:'Instant win',art:'voucher',status:'Active',end:'2026-10-31',countries:['United Kingdom'],requirement:'One code from an eligible can',short:'Can code required',description:'Find out straight away whether your example entry wins a £10 digital gift card. This is a simulated instant-win experience.',step:'Enter the example can code',code:true},
 {id:'weekend-pass',brand:'Rockstar',title:'Make a weekend of it.',prize:'Two weekend music passes',type:'Prize draw',art:'music',status:'Active',end:'2026-11-15',countries:['United Kingdom','France'],requirement:'A free online entry',short:'No purchase required',description:'A weekend full of live music. Explore a second example draw from Rockstar.',step:'Confirm your example entry',code:false},
 {id:'snack-night',brand:'Doritos',title:'Your next night in is covered.',prize:'A £5 snack voucher',type:'Instant win',art:'voucher',status:'Ended',end:'2026-09-30',countries:['United Kingdom'],requirement:'One code from an eligible pack',short:'Entry is now closed',description:'This example promotion has ended. Keep its details available for reference, with entry clearly closed.',step:'Entry closed',code:true},
 {id:'pepsi-weekend',brand:'Pepsi',title:'A weekend worth remembering.',prize:'A city break for two',type:'Prize draw',art:'trip',status:'Ended',end:'2026-09-20',countries:['United Kingdom','France','Germany'],requirement:'A free online entry',short:'Entry is now closed',description:'An archived example prize draw. This promotion is shown separately from available offers.',step:'Entry closed',code:false}
];
const brands=['Pepsi','Doritos','Rockstar','7UP'];
const seed={signed:true,name:'Alex',country:'United Kingdom',favourites:['Doritos','Pepsi'],saved:[],entries:[{id:'live-music',outcome:'draw',date:'2026-10-15',ref:'JOY-DEMO-1001'},{id:'instant-break',outcome:'loss',date:'2026-10-14',ref:'JOY-DEMO-1002'}],notifications:false};
let state;try{state=JSON.parse(localStorage.getItem('joy-prototype-v1'))||structuredClone(seed)}catch{state=structuredClone(seed)}
let filters={q:'',brand:'All brands',type:'All types',status:'Available',sort:'recommended'},profileTab='Activity',menuOpen=false,entryDraft={},toastTimer,returnFocus;
const persist=()=>{try{localStorage.setItem('joy-prototype-v1',JSON.stringify(state))}catch{}};
const date=s=>new Date(s+'T12:00:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'});
const theme=b=>b==='Doritos'||b==='Rockstar'?b:'JOY';
const entry=p=>state.entries.find(e=>e.id===p.id);
const inCountry=p=>p.countries.includes(state.country);
const status=p=>p.status==='Ended'?'Ended':state.signed&&entry(p)?'Entered':p.status;
const badge=(s)=>`<span class="badge ${s==='Ended'?'ended':s==='Entered'?'entered':s==='Ending soon'?'soon':''}">${s==='Entered'?icon('check'):s==='Ending soon'?icon('clock'):''}${s}</span>`;
const route=()=>location.hash.slice(1)||'/';
const go=p=>{if(route()===p)render();else location.hash=p};
const button=(label,path,cls='')=>`<a class="btn ${cls}" href="#${path}">${label}${icon('arrow')}</a>`;
const toast=msg=>{clearTimeout(toastTimer);$('#toast').textContent=msg;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500)};
function art(p,save=true){return `<div class="card-art ${p.art}" data-theme="${theme(p.brand)}"><span class="brand-tag">${p.brand}</span>${save?`<button class="icon-btn save" data-save="${p.id}" aria-label="${state.saved.includes(p.id)?'Unsave':'Save'} ${esc(p.prize)}" aria-pressed="${state.saved.includes(p.id)}">${icon('heart')}</button>`:''}${p.art==='console'?`<span class="disc"></span><img class="product" src="assets/console.png" alt="PlayStation 5 console and controller">`:`<div class="ticket ${p.art==='voucher'?'second':''}" aria-hidden="true"><div class="ticket-top">${p.art==='music'?'LIVE MUSIC':p.art==='trip'?'CITY BREAK':'DIGITAL GIFT'}</div><strong>${p.art==='music'?'YOU + 1':p.art==='trip'?'WEEKEND':p.id==='snack-night'?'£5':'£10'}</strong><div class="ticket-bottom">${p.art==='music'?'Two tickets. One great night.':p.art==='trip'?'Two people. A new adventure.':'A little something for you.'}</div></div>`}</div>`}
function card(p){return `<article class="promo-card ${p.status==='Ended'?'ended-card':''}">${art(p)}<div class="card-body"><div class="row between">${badge(status(p))}<span class="type-label">${p.type}</span></div><a class="card-title" href="#/promotion/${p.id}"><h3>${p.prize}</h3></a><p class="small">${p.title}</p><div class="meta"><span>${icon('user')}${state.country} · 18+ · Example</span><span>${icon('ticket')}${p.short}</span></div><div class="card-bottom"><span class="small muted">${p.status==='Ended'?'Ended':'Ends'} ${date(p.end).replace(' 2026','')}</span><a href="#/promotion/${p.id}">${p.status==='Ended'?'View archive':'View promotion'}${icon('arrow')}</a></div></div></article>`}
function cards(list){return list.length?list.map(card).join(''):empty('No promotions here yet','Try another brand or check back for new example promotions.','Browse promotions','/promotions')}
function empty(title,copy,label,path){return `<div class="empty">${icon('search')}<h3>${title}</h3><p>${copy}</p>${label?button(label,path,'secondary'):''}</div>`}
function brandTile(b){return `<div class="brand-tile" data-theme="${theme(b)}"><a href="#/brand/${b}"><span class="brand-dot"></span>${b}</a><button class="icon-btn" data-favourite="${b}" aria-label="${state.favourites.includes(b)?'Unfollow':'Follow'} ${b}" aria-pressed="${state.favourites.includes(b)}">${icon('heart')}</button></div>`}
function entryRows(){return state.entries.length?`<div class="entry-list">${state.entries.map(e=>{const p=offers.find(p=>p.id===e.id);return `<div class="entry-row"><div class="entry-thumb">${p.art==='console'?'<img src="assets/console.png" alt="">':icon('ticket')}</div><div class="entry-main"><h3>${p.prize}</h3><p>${p.brand} · ${p.type} · Entered ${date(e.date)}</p></div><span class="badge entered">${e.outcome==='draw'?'Awaiting draw':e.outcome==='win'?'Example win':'No prize this time'}</span><a class="text-btn" href="#/result/${e.id}">View ${e.outcome==='draw'?'entry':'result'} ${icon('arrow')}</a></div>`}).join('')}</div>`:empty('Your first entry starts here','Once you try a promotion, its confirmation and result will be saved here.','Explore promotions','/promotions')}
function header(){const r=route();return `<div class="prototype-bar">Design prototype · All offers and results are illustrative.<span class="desktop-only"> Example date: 16 Oct 2026.</span><a href="#/about">About this prototype</a></div><header class="header ${menuOpen?'menu-open':''}"><div class="container header-inner"><a href="#/" aria-label="JOY home"><img class="logo" src="assets/joy-white.png" alt="JOY by PepsiCo"></a><nav class="nav" aria-label="Main navigation">${[['/','Home'],['/promotions','Promotions'],['/brands','Brands']].map(([p,t])=>`<a href="#${p}" ${r===p||(p==='/brands'&&r.startsWith('/brand/'))||(p==='/promotions'&&r.startsWith('/promotion/'))?'aria-current="page"':''}>${t}</a>`).join('')}</nav><div class="header-tools"><label class="country-control">${icon('globe')}<span class="visually-hidden">Example market</span><select id="country">${['United Kingdom','France','Germany','Spain'].map(c=>`<option ${c===state.country?'selected':''}>${c}</option>`).join('')}</select></label>${state.signed?`<a class="profile-link" href="#/profile" aria-label="My JOY account"><span class="avatar">${esc(state.name[0]||'A')}</span><span class="name">My JOY</span></a>`:`<a class="text-btn" href="#/join">Log in</a>`}<button class="icon-btn mobile-menu" data-action="menu" aria-label="Toggle navigation" aria-expanded="${menuOpen}">${icon(menuOpen?'close':'menu')}</button></div></div></header>`}
function footer(){return `<footer class="footer"><div class="container"><div class="footer-top"><a href="#/" aria-label="JOY home"><img class="footer-logo" src="assets/joy-white.png" alt="JOY by PepsiCo"></a><div class="footer-links"><a href="#/help">Help & FAQs</a><a href="#/terms">Example terms</a><a href="#/privacy">Privacy</a><a href="#/about">Design rationale</a><button class="text-btn small" data-action="toggle-auth">${state.signed?'View logged-out example':'View logged-in example'}</button></div></div><p class="footer-note">JOY by PepsiCo · Independent research prototype. No live promotions, purchases or prize claims. Brand names and supplied assets are used for design demonstration.</p></div></footer>`}
function hero(guest=false){return `<section class="hero ${guest?'guest-hero':''}" aria-label="Featured example promotion"><div class="hero-copy"><span class="eyebrow">${guest?'More moments of JOY':'Featured example · Doritos'}</span><${guest?'h1':'h2'}>${guest?'Your favourites. More JOY.':'Turn game night into a great night.'}</${guest?'h1':'h2'}><p>${guest?'Discover rewards from the brands you love, with a clear path from entry to result.':'A PlayStation®5 console could be yours in this example prize draw. See the prize and entry requirements before you begin.'}</p><div class="row">${button(guest?'Explore promotions':'See the prize',guest?'/promotions':'/promotion/game-night','white')}${guest?'<a class="text-btn" style="color:white" href="#/join">Join JOY</a>':''}</div><span class="small">${guest?'Browse first. Join when you’re ready.':'18+ · Eligible pack code · Ends 8 Nov 2026'}</span></div><div class="hero-art"><span class="halo"></span><span class="art-sticker">${guest?'Good things ahead':'Game night, upgraded'}</span><img src="assets/console.png" alt="Example prize: PlayStation 5 console"><span class="art-caption">Illustrative promotion</span></div></section>`}
function home(){const active=offers.filter(p=>p.status!=='Ended'&&inCountry(p));const recommended=[...active].sort((a,b)=>(state.signed?Number(!!entry(a))-Number(!!entry(b)):0)||Number(state.favourites.includes(b.brand))-Number(state.favourites.includes(a.brand))).slice(0,3);return `${state.signed?`<div class="intro row between"><div><span class="eyebrow">Your JOY, all in one place</span><h1>Hi ${esc(state.name)}, good to see you.</h1><p>Find something to look forward to.</p></div><a class="text-btn" href="#/profile">Your activity ${icon('arrow')}</a></div>`:''}${hero(!state.signed)}${state.signed?`<div class="activity-strip"><div class="stat"><span class="stat-icon">${icon('ticket')}</span><div><strong>${state.entries.length} entries to follow</strong><p>All your participation, together.</p></div></div><div class="stat"><span class="stat-icon">${icon('check')}</span><div><strong>${state.entries.filter(e=>e.outcome!=='draw').length} ${state.entries.filter(e=>e.outcome!=='draw').length===1?'result':'results'} ready</strong><p>Check what happened next.</p></div></div><a class="text-btn" href="#/profile">See my activity ${icon('arrow')}</a></div>`:''}<section class="section"><div class="section-head"><div><h2>${state.signed?'Suggested for you':'Something worth a look'}</h2><p class="small">${state.signed?'Based on your favourite brands':'Example promotions in '+state.country} · ${active.length} available</p></div><a class="text-btn" href="#/promotions">View all ${icon('arrow')}</a></div><div class="grid">${cards(recommended)}</div></section>${!state.signed?`<section class="section"><div class="section-head"><h2>A little less effort. A little more JOY.</h2></div>${steps(['Find your reward','See how to take part','Know what happens next'],['Browse prizes from your favourite brands. Each offer explains what you could receive.','Check your country, eligibility and any purchase or code requirements first.','See an instant result or a clear draw confirmation, then track it in My JOY.'])}</section>`:''}${state.signed?`<section class="section"><div class="section-head"><div><h2>Your entered promotions</h2><p class="small">No guessing. See your entry and its current status.</p></div><a class="text-btn" href="#/profile">All activity ${icon('arrow')}</a></div>${entryRows()}</section>`:''}<section class="section"><div class="section-head"><div><h2>${state.signed?'Make it more you':'Your favourites, together'}</h2><p class="small">Follow brands to shape your suggested promotions.</p></div><a class="text-btn" href="#/brands">All brands ${icon('arrow')}</a></div><div class="brand-grid">${brands.map(brandTile).join('')}</div></section><section class="section wide-cta"><div><h2>Only the updates you want.</h2><p>Choose which promotion news you hear about.</p></div><a class="btn secondary" href="#/profile/preferences">Manage preferences ${icon('arrow')}</a></section>`}
function steps(t,copy){return `<div class="steps">${t.map((x,i)=>`<div class="step"><span class="step-number">${i+1}</span><div><h3>${x}</h3><p>${copy[i]}</p></div></div>`).join('')}</div>`}
function filtered(){let list=offers.filter(p=>inCountry(p)&&(filters.brand==='All brands'||p.brand===filters.brand)&&(filters.type==='All types'||p.type===filters.type)&&(!filters.q||`${p.brand} ${p.title} ${p.prize} ${p.type}`.toLowerCase().includes(filters.q.toLowerCase()))&&(filters.status==='Available'?p.status!=='Ended':filters.status==='Entered'?state.signed&&!!entry(p):filters.status==='Saved'?state.saved.includes(p.id):p.status==='Ended'));if(filters.sort==='ending')list.sort((a,b)=>a.end.localeCompare(b.end));else if(filters.sort==='brand')list.sort((a,b)=>a.brand.localeCompare(b.brand));else list.sort((a,b)=>Number(state.favourites.includes(b.brand))-Number(state.favourites.includes(a.brand)));return list}
const opts=(a,v)=>a.map(t=>`<option ${t===v?'selected':''}>${t}</option>`).join('');
function gallery(){return `<div class="intro"><span class="eyebrow">Find your next moment</span><h1>Good things are waiting.</h1><p>Prizes up front. Requirements made clear. Explore what’s available to you.</p></div><div class="filters"><div class="field"><label for="search">Find a promotion</label><div class="search-wrap">${icon('search')}<input id="search" type="search" placeholder="Search prizes, brands or promotions" value="${esc(filters.q)}"></div></div><div class="field"><label for="brand-filter">Brand</label><select id="brand-filter">${opts(['All brands',...brands],filters.brand)}</select></div><div class="field"><label for="type-filter">Promotion type</label><select id="type-filter">${opts(['All types','Prize draw','Instant win'],filters.type)}</select></div><div class="field"><label for="availability">Availability</label><select id="availability">${opts(['Available','Entered','Saved','Ended'],filters.status)}</select></div></div><div class="results-toolbar"><div class="tabs" aria-label="Promotion availability">${['Available','Entered','Saved','Ended'].map(s=>`<button class="tab" data-status="${s}" aria-pressed="${filters.status===s}">${s}</button>`).join('')}</div><label class="small">Sort by <select class="sort" id="sort"><option value="recommended" ${filters.sort==='recommended'?'selected':''}>Recommended</option><option value="ending" ${filters.sort==='ending'?'selected':''}>Ending soonest</option><option value="brand" ${filters.sort==='brand'?'selected':''}>Brand A–Z</option></select></label></div><div class="section-head"><p id="result-count" role="status" class="small"></p><button class="text-btn small" data-action="clear-filters">Clear filters</button></div><div id="promotion-grid" class="grid"></div>`}
function updateResults(){if(!$('#promotion-grid'))return;const list=filtered();$('#result-count').textContent=`${list.length} ${list.length===1?'promotion':'promotions'} · ${state.country} · Illustrative offers`;$('#promotion-grid').innerHTML=list.length?list.map(card).join(''):empty(filters.status==='Entered'&&!state.signed?'Log in to see your entries':'No matching promotions',filters.status==='Ended'?'There are no archived examples for these filters.':'Try clearing a filter or choosing another example market.','',null)+`<div class="row"><button class="btn secondary" data-action="clear-filters">Reset filters</button>${!state.signed&&filters.status==='Entered'?button('Log in','/join'):''}</div>`}
function details(p){const e=entry(p),eligible=inCountry(p),closed=p.status==='Ended';return `<nav class="breadcrumbs" aria-label="Breadcrumb"><a href="#/">Home</a><span>/</span><a href="#/promotions">Promotions</a><span>/</span><span>${p.brand}</span></nav><div data-theme="${theme(p.brand)}"><div class="detail-grid">${art(p,false)}<div class="detail-copy"><div class="row">${badge(status(p))}<span class="type-label">${p.type} · Example promotion</span></div><div><p class="eyebrow">${p.brand}</p><h1>${p.prize}</h1></div><p>${p.description}</p><div class="meta"><span>${icon('pin')}${p.countries.join(', ')} · Age 18+</span><span>${icon('clock')}${closed?'Ended':'Entry closes'} ${date(p.end)} · 23:59 local market time</span><span>${icon('ticket')}${p.requirement}</span></div><div class="notice">${p.type==='Instant win'?'Instant win: you’ll see a simulated win or no-prize result after submitting.':'Prize draw: entering gives you a chance to win. You’ll receive an entry confirmation, not an instant prize.'}</div>${closed?'<button class="btn" disabled>Entry closed</button>':!eligible?`<div class="notice">This example isn’t available in ${state.country}. Choose a listed market to explore the flow.</div><button class="btn" disabled>Not available in this market</button>`:state.signed&&e?button('View your entry','/result/'+p.id):button(state.signed?'Take part':'Log in to take part',state.signed?'/enter/'+p.id:'/join?next='+p.id)}<p class="small">Demo only. No purchase, real code, account or prize is needed.</p></div></div><nav class="detail-nav" aria-label="Promotion sections"><a href="#/promotion/${p.id}" data-scroll="how">How to take part</a><a href="#/promotion/${p.id}" data-scroll="faq">FAQs</a><a href="#/promotion/${p.id}" data-scroll="rules">Example rules</a></nav><section class="section" id="how"><div class="section-head"><h2>Know what to do before you start.</h2></div>${steps(['Check the requirements',p.code?'Have your code ready':'Confirm your entry',p.type==='Instant win'?'See your result':'You’re in the draw'],[`For this example: age 18+, resident in an eligible market. ${p.short}.`,p.code?'For testing, use JOY2026. Don’t buy a product or enter a real pack code.':'This example needs no purchase. Confirm eligibility in one simple step.',p.type==='Instant win'?'Your result appears here and stays in your activity. No extra survey.':'Your confirmation is saved in My JOY. The result date is shown with your entry.'])}</section><section class="section faq" id="faq"><div class="section-head"><h2>A few useful answers.</h2></div><details><summary>Is a prize guaranteed?</summary><p>No. ${p.type==='Prize draw'?'This example is a chance-based draw; real odds depend on the number of valid entries and available prizes.':'An instant-win entry can receive a win or a no-prize result.'} Prototype outcomes are selected for testing and do not represent actual odds.</p></details><details><summary>Will I need to sign in again?</summary><p>This prototype keeps you in one JOY journey. If a real offer requires an external provider, the destination and any extra sign-in requirements must be explained before leaving JOY.</p></details><details><summary>What happens after I enter?</summary><p>${p.type==='Instant win'?'You see a result immediately and can return to it from My JOY.':'Your entry is saved as awaiting draw. This example shows a result date of '+date(p.end)+'.'} No real emails are sent.</p></details></section><section class="section faq" id="rules"><h2>Example rules, clearly stated.</h2><p style="margin-top:16px">Illustrative eligibility: residents aged 18+ in ${p.countries.join(', ')}. One simulated entry per promotion. Entry closes ${date(p.end)} at 23:59 local market time. ${p.requirement}. These are prototype assumptions, not official promotion terms.</p><p class="notice" style="margin-top:16px">A live launch needs approved market-specific rules, prize inventory, odds or draw details, entry limits, fulfilment, privacy terms and verified eligibility. No live offers are represented here.</p></section></div>`}
function brandsPage(){return `<div class="intro"><span class="eyebrow">More favourites. One place.</span><h1>Find your kind of JOY.</h1><p>Explore each brand’s promotions. Follow your favourites for more relevant suggestions.</p></div><div class="brand-grid">${brands.map(brandTile).join('')}</div><section class="section"><div class="section-head"><h2>From the brands you follow</h2></div><div class="grid">${cards(offers.filter(p=>p.status!=='Ended'&&inCountry(p)&&state.favourites.includes(p.brand)))}</div></section>`}
function brandPage(b){const list=offers.filter(p=>p.brand===b&&inCountry(p)&&p.status!=='Ended'),ended=offers.filter(p=>p.brand===b&&inCountry(p)&&p.status==='Ended');return `<nav class="breadcrumbs" aria-label="Breadcrumb"><a href="#/brands">Brands</a><span>/</span><span>${b}</span></nav><div data-theme="${theme(b)}"><section class="brand-hero"><div><div class="eyebrow">Your brand. Your next reward.</div><h1>${b}</h1><p>${b==='Doritos'?'Make your next night in a big one.':b==='Rockstar'?'Good things for your next break.':'Discover something to look forward to.'} Browse only ${b} promotions available in your example market.</p></div><button class="btn white" data-favourite="${b}" aria-pressed="${state.favourites.includes(b)}">${icon('heart')}${state.favourites.includes(b)?'Following':'Follow brand'}</button></section><section class="section"><div class="section-head"><div><h2>Available from ${b}</h2><p class="small">${list.length} promotions · ${state.country}</p></div></div><div class="grid">${cards(list)}</div></section>${ended.length?`<section class="section"><div class="section-head"><h2>Past promotions</h2><span class="small muted">Entry is closed</span></div><div class="grid">${ended.map(card).join('')}</div></section>`:''}</div>`}
function flowSteps(current){return `<div class="flow-steps" aria-label="Participation progress"><span class="${current===1?'current':''}">1 · Requirements</span><span class="${current===2?'current':''}">2 · Entry</span><span class="${current===3?'current':''}">3 · ${current===3?'Result':'Confirmation'}</span></div>`}
function enter(p){if(!state.signed)return join(p.id);if(p.status==='Ended'||!inCountry(p))return details(p);if(entry(p)&&entryDraft.replay!==p.id)return result(p);return `<div class="flow"><a class="text-btn" href="#/promotion/${p.id}">${icon('back')} Back to promotion</a><div class="flow-heading"><p class="eyebrow">${p.brand} · ${p.type}</p><h1>${p.prize}</h1></div>${flowSteps(2)}<form id="entry-form" data-id="${p.id}" class="panel form-stack" novalidate><div><h2>${p.code?'One code. You’re ready to go.':'Your entry, one step away.'}</h2><p style="margin-top:12px">${p.type==='Instant win'?'You’ll see your result on the next screen.':'You’re entering a prize draw. A prize isn’t guaranteed.'}</p></div><div class="notice">Testing only · ${p.code?'Use the example code <strong>JOY2026</strong>. No real purchase or code is required.':'No purchase or personal information required for this example.'}</div>${p.code?`<div class="field"><label for="entry-code">Example ${p.brand==='Rockstar'?'can':'pack'} code (required)</label><input id="entry-code" name="code" type="text" autocomplete="off" spellcheck="false" maxlength="20" aria-describedby="code-help code-error" value="${esc(entryDraft.code||'')}" placeholder="e.g. JOY2026"><span id="code-help" class="small muted">7 characters. Spaces and letter case don’t matter.</span><span id="code-error" class="error"></span></div>`:''}<label class="check"><input type="checkbox" id="eligible" ${entryDraft.eligible?'checked':''}><span>I confirm the example eligibility (required).<small>Age 18+ and resident in ${state.country}. This does not verify your real identity.</small></span></label><label class="check"><input type="checkbox" id="rules-agree" ${entryDraft.rules?'checked':''}><span>I understand this is a simulated entry (required).<small><a href="#/promotion/${p.id}" data-action="save-draft">Read example rules</a>. No prize or email will be issued.</small></span></label><div id="form-error" class="error" role="alert"></div><div class="demo-controls field"><label for="test-outcome">Prototype test scenario</label><select id="test-outcome">${p.type==='Instant win'?'<option value="loss">No prize result</option><option value="win">Winning result</option>':'<option value="draw">Entry confirmation</option>'}<option value="error">Recoverable connection error</option></select><span class="small muted">This tester control selects the demonstration outcome. It is not part of a live promotion.</span></div><div class="form-actions"><a class="text-btn" href="#/promotion/${p.id}">Cancel</a><button class="btn" type="submit">${p.type==='Instant win'?'See my result':'Submit example entry'} ${icon('arrow')}</button></div></form></div>`}
function result(p){if(!state.signed)return join(p.id);const e=entry(p);if(!e)return empty('No entry yet','Take a look at the promotion requirements before entering.','View promotion','/promotion/'+p.id);const win=e.outcome==='win',draw=e.outcome==='draw';return `<div class="flow"><a class="text-btn" href="#/profile">${icon('back')} Back to my activity</a><div class="flow-heading"><p class="eyebrow">${p.brand} · Example ${p.type.toLowerCase()}</p></div>${flowSteps(3)}<section class="panel result"><span class="result-icon ${!win?'neutral':''}">${icon(win?'gift':draw?'check':'ticket')}</span><span class="eyebrow">${win?'Simulated winning result':draw?'Example entry confirmed':'Simulated result'}</span><h1>${win?'A little JOY, just for you.':draw?'You’re in the draw.':'No prize this time.'}</h1><p>${win?'In this example, you’ve won '+p.prize.toLowerCase()+'.':draw?'Your example entry for '+p.prize.toLowerCase()+' is saved. There’s nothing else you need to do.':'Your entry was received, but it wasn’t a winning entry. You can keep track of this result in My JOY.'}</p>${win&&p.art==='console'?'<img class="result-product" src="assets/console.png" alt="Example console prize">':''}<div class="notice"><strong>${draw?'What happens next':win?'About your example reward':'Your entry is saved'}</strong><p class="small" style="margin-top:8px">${draw?'Example result date: '+date(p.end)+'. A real service would provide the approved notification and claim process.':win?'This prototype cannot issue or redeem prizes. A live win would show a claim deadline, delivery method and support details here.':'No additional survey or information is needed. Explore other promotions whenever you’re ready.'}</p></div><p class="small">Reference ${e.ref} · Entered ${date(e.date)}<br>Simulation only. No real reward or email.</p><div class="row">${button('My activity','/profile')}${button('Explore promotions','/promotions','secondary')}</div><div class="demo-controls"><button class="text-btn" data-replay="${p.id}">Test another outcome</button><p class="small">Replaces this simulated result. No duplicate entry is created.</p></div></section></div>`}
function join(next=''){return `<div class="flow"><div class="flow-heading"><span class="eyebrow">Welcome to JOY</span><h1>A little more, from your favourites.</h1><p style="margin-top:16px">Explore the example member experience. This creates no real account.</p></div><form id="join-form" data-next="${esc(next)}" class="panel form-stack" novalidate><div class="notice">Prototype sign-in · No email, password or date of birth is collected.</div><div class="field"><label for="demo-name">Example display name</label><input id="demo-name" maxlength="24" value="Alex" autocomplete="off"></div><div class="field"><label for="join-country">Example market</label><select id="join-country">${opts(['United Kingdom','France','Germany','Spain'],state.country)}</select></div><label class="check"><input type="checkbox" id="join-agree"><span>I understand that offers and participation are simulated (required).<small><a href="#/terms">Example terms</a> · <a href="#/privacy">Prototype privacy</a></small></span></label><div class="error" id="join-error" role="alert"></div><button class="btn" type="submit">Continue as example member ${icon('arrow')}</button><a class="text-btn" href="#/promotions">Keep browsing as a guest</a></form></div>`}
function profile(){if(!state.signed)return join();let content='';if(profileTab==='Activity')content=`<div class="section-head"><div><h2>Your activity</h2><p class="small">${state.entries.length} example entries · Results and confirmations</p></div></div>${entryRows()}<div class="notice" style="margin-top:24px">Entries are participation records, not points or a redeemable balance. No verified points or coins programme is assumed.</div>`;else if(profileTab==='Rewards')content=`<h2>Your rewards</h2><div style="margin-top:24px">${state.entries.some(e=>e.outcome==='win')?state.entries.filter(e=>e.outcome==='win').map(e=>`<div class="panel stack"><h3>${offers.find(p=>p.id===e.id).prize}</h3><p>Example reward only · No real claim or redemption</p>${button('View example result','/result/'+e.id,'secondary')}</div>`).join(''):empty('No rewards to claim','Try the instant-win example and select “Winning result” to explore the reward screen. Real rewards would appear here after a verified win.','Explore promotions','/promotions')}</div>`;else if(profileTab==='Favourite brands')content=`<h2>Your favourite brands</h2><p style="margin:12px 0 24px">Suggestions use only the brands you follow. No hidden profiling.</p><div class="brand-grid" style="grid-template-columns:repeat(2,minmax(0,1fr))">${brands.map(brandTile).join('')}</div>`;else if(profileTab==='Preferences')content=`<form id="preferences-form" class="panel prefs"><h2>Only the updates you want.</h2><label class="check"><input id="news-pref" type="checkbox" ${state.notifications?'checked':''}><span>Promotion news from my favourite brands<small>Optional. Saved locally for this demonstration. No email is sent.</small></span></label><div class="notice">Entry status is always available in My JOY. You don’t need marketing notifications to participate.</div><button class="btn" type="submit">Save preferences</button></form>`;else content=`<form id="personal-form" class="panel prefs"><h2>Personal information & privacy</h2><div class="field"><label for="profile-name">Example display name</label><input id="profile-name" value="${esc(state.name)}" maxlength="24" required></div><p class="small">Your example market is ${state.country}. Change it in the header. No date of birth, address or email is stored.</p><button class="btn" type="submit">Save name</button><a href="#/privacy">How this prototype stores data</a><button type="button" class="btn secondary" data-action="reset-dialog">Reset example data</button></form>`;return `<div class="intro"><span class="eyebrow">Your JOY</span><h1>A home for your good things.</h1><p>Your entries, favourite brands and preferences, together.</p></div><div class="profile-layout"><aside><div class="profile-head"><span class="avatar">${esc(state.name[0])}</span><div><strong>${esc(state.name)}</strong><p class="small">Example member</p></div></div><nav class="side-nav" aria-label="Account sections">${['Activity','Rewards','Favourite brands','Preferences','Personal information'].map(t=>`<button data-profile="${t}" aria-pressed="${profileTab===t}">${t}</button>`).join('')}</nav></aside><div>${content}</div></div>`}
function info(kind){if(kind==='about')return rationale();const privacy=kind==='privacy',terms=kind==='terms';return `<div class="rationale"><span class="eyebrow">${privacy?'Your information':terms?'Before taking part':'A little help'}</span><h1>${privacy?'Prototype privacy':terms?'Example terms':'Good questions. Clear answers.'}</h1><div class="section faq">${privacy?'<p>This browser-only prototype stores your example display name, market, favourite brands, saved promotions, notification setting and simulated entries in local storage on this device. It does not send those values to a backend or marketing service.</p><p>No real sign-in, identity verification, purchases, emails or prize claims are implemented. Private hosting access is separate from the simulated JOY login. Hosting providers may process ordinary access logs.</p><p>Use Reset example data in Personal information to return to the starter example. Do not enter real pack codes or sensitive personal data.</p><a class="btn secondary" href="#/profile">Manage my example data</a>':terms?'<p>All promotions, eligibility, dates, prizes, entry limits and outcomes shown here are illustrative design content. None is an actual offer by PepsiCo or another brand.</p><p>The example date is fixed at 16 October 2026 so Active, Ending soon and Ended states remain predictable for testing. One entry per example promotion is allowed. The supplied test code is JOY2026.</p><p>Official country-specific promotion terms, age limits, purchasing requirements, odds, draw operations and fulfilment would need approval before a real launch. These pages do not provide legal terms for a live promotion.</p>':'<details open><summary>How does participation work?</summary><p>Browse a promotion, check the prize and example requirements, and select Take part. Draws confirm your entry. Instant wins show a result immediately.</p></details><details><summary>What is the difference between a draw and an instant win?</summary><p>A draw confirms participation and tells you when to expect a result. An instant win returns a result immediately. Neither guarantees a prize.</p></details><details><summary>Do entries earn points or coins?</summary><p>No points conversion is assumed. Entries, results and illustrative rewards are tracked separately.</p></details><details><summary>Why are some promotions missing?</summary><p>The gallery shows available examples for your selected market. Ended offers have their own filter. Brand pages show only that brand’s offers.</p></details><details><summary>Can I claim a prize?</summary><p>No. This is a design prototype with simulated entries and outcomes.</p></details>'}</div></div>`}
function rationale(){return `<article class="rationale"><span class="eyebrow">Research → structure → experience</span><h1>More clarity. More JOY.</h1><p style="margin-top:24px">A responsive, interactive redesign built from the supplied research, wireframes and JOY design system. This prototype is ready for usability testing; it has not been validated with participants.</p><h2>What informed the design</h2><p>The 39-page PepsiCo × Purdue UX report records six interviews with people aged 18–24 from the US and UK and three cognitive walkthroughs with UX students aged 18–24. These are directional findings, not a representative EU market study. FigJam includes raw notes, synthesis and proposed concepts.</p><table><thead><tr><th>Research finding</th><th>Design decision</th><th>Screen affected</th></tr></thead><tbody>${[
['Prizes motivated participation; requirements often came first (PDF pp. 14–16).','Put the prize, eligibility, deadline and entry requirement before the primary action.','Cards and details'],
['Active and expired promotions looked alike (pp. 14, 16).','Default to available offers; separate ended offers, label their status and disable entry.','Gallery and brand pages'],
['Participants struggled to find relevant brand promotions (p. 16).','Search, brand/type filters and country-specific examples; brand pages contain only their own offers.','Discovery'],
['A second sign-in and additional agreements fragmented participation (pp. 16, 26).','One session and one entry form; retain the intended promotion after example login.','Onboarding and entry'],
['Post-loss surveys felt intrusive; instant outcomes were unclear (pp. 14, 16).','Explain the result type in advance and show neutral no-prize copy with useful next actions.','Details and results'],
['Interviews favoured understandable value and ongoing benefits (pp. 17–19).','State the tangible prize, show follow-up activity and personalise by explicitly followed brands.','Home and profile'],
['Point value and expiry were unclear; reward thresholds felt high (pp. 18–19).','Do not invent a shared currency or conversion. Keep entries and rewards distinct.','Home and profile'],
['Navigation did not show the current location (p. 14).','Active navigation, explicit breadcrumbs and return links.','All screens']
].map(r=>'<tr>'+r.map(c=>`<td>${c}</td>`).join('')+'</tr>').join('')}</tbody></table><h2>What was retained and refined</h2><p>Retained: Home / Promotions / Brands navigation; guest and member homes; Suggested and Entered promotions; prize-first detail sections; steps, FAQs and terms; central result panels. Refined: the large gallery carousel becomes a compact discovery introduction; unrelated brand news is removed; ended offers are separated. Guest promotions precede the how-to section to surface value sooner. The unverified “one entry away” reward meter becomes an honest activity summary.</p><h2>The JOY visual system, in code</h2><p>Uses JOY #1443FF and the exact semantic themes for Doritos and Rockstar, nine supplied type styles, Galano typography from the live JOY website, the spacing scale, 20px card corners, 44px pill controls, 24px card padding and 12px × 20px button padding. The live JOY GB site supplies the blue header and footer, white logo, yellow #FFE600 hero buttons, Galano font and decorative shapes. Fields and status badges retain the Figma variants. The promotion card extends the supplied card foundation with the discovery information the research calls for. Pepsi and 7UP use the shared JOY theme because no dedicated theme was supplied.</p><h2>Explore the connected journeys</h2><p>Switch guest/member examples in the footer. Search and filter promotions. Follow brands. Open a promotion and submit JOY2026. Choose a no-prize, winning or connection-error scenario for instant win; view the saved result in My JOY. Reset example data to repeat a completed flow.</p><h2>Scope and next validation</h2><p>All offers, rules and dates are illustrative. Ticket artwork is a prize illustration; the console comes from the supplied wireframes; the white JOY logo, font and decoration come from the live JOY site. No artificial points, real authentication, CRM, email, draw service or redemption is implemented.</p><p>Next: test reward comprehension, finding an eligible promotion, distinguishing instant win from a draw, recovering from invalid input and locating a result. Include participants in target EU markets and assistive-technology users. Confirm market rules and content with the programme team before a live implementation.</p><div class="row"><a href="https://www.joy-pepsico.eu/en-gb/" target="_blank" rel="noopener">Live JOY visual reference ↗</a><a href="https://www.figma.com/design/AJ0GKjFjDNvEsD4MfdyZaN/AI-Assisted-Design-System?node-id=14-2" target="_blank" rel="noopener">Design system ↗</a><a href="https://www.figma.com/board/C0aRujYsmrf64Mk2EeYSJm/Figjam-Documentation?node-id=0-1" target="_blank" rel="noopener">Research board ↗</a><a href="https://www.figma.com/design/IMEy8gioQJFpGIgb9qIUJe/Wireframes?node-id=0-1" target="_blank" rel="noopener">Wireframes ↗</a></div></article>`}
function render(){const r=route();let content;document.body.removeAttribute('data-theme');if(r==='/')content=home();else if(r==='/promotions')content=gallery();else if(r==='/brands')content=brandsPage();else if(r.startsWith('/brand/')){const b=decodeURIComponent(r.split('/')[2]);content=brands.includes(b)?brandPage(b):empty('Brand not found','Browse the available example brands.','All brands','/brands')}else if(r.startsWith('/promotion/')||r.startsWith('/enter/')||r.startsWith('/result/')){const p=offers.find(p=>p.id===r.split('/')[2]);content=p?(r.startsWith('/enter/')?enter(p):r.startsWith('/result/')?result(p):details(p)):empty('Promotion not found','This link does not match an example promotion.','Browse promotions','/promotions')}else if(r.startsWith('/join'))content=join(r.split('next=')[1]||'');else if(r.startsWith('/profile')){if(r.endsWith('/preferences'))profileTab='Preferences';content=profile()}else if(['/about','/privacy','/terms','/help'].includes(r))content=info(r.slice(1));else content=empty('Let’s get you back to JOY.','That page isn’t part of this prototype.','Go home','/');$('#app').innerHTML=header()+`<main class="main container" id="main" tabindex="-1">${content}</main>`+footer();updateResults();document.title=($('.main h1')?.textContent||'Explore rewards')+' | JOY';}
function openDialog(title,body){returnFocus=document.activeElement;$('#dialog').innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2><button class="icon-btn" data-action="close-dialog" aria-label="Close dialog">${icon('close')}</button></div><div class="dialog-body">${body}</div>`;$('#dialog').showModal()}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.classList.contains('skip')){e.preventDefault();$('#main').focus();$('#main').scrollIntoView();return}if(b.dataset.replay){entryDraft={replay:b.dataset.replay};go('/enter/'+b.dataset.replay);return}if(b.dataset.scroll){e.preventDefault();$('#'+b.dataset.scroll)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});return}if(b.dataset.favourite){const v=b.dataset.favourite;state.favourites=state.favourites.includes(v)?state.favourites.filter(x=>x!==v):[...state.favourites,v];persist();render();document.querySelector(`[data-favourite="${v}"]`)?.focus({preventScroll:true});toast(state.favourites.includes(v)?`${v} followed. Suggestions updated.`:`${v} unfollowed.`);return}if(b.dataset.save){const v=b.dataset.save;state.saved=state.saved.includes(v)?state.saved.filter(x=>x!==v):[...state.saved,v];persist();const saved=state.saved.includes(v);b.setAttribute('aria-pressed',String(saved));b.setAttribute('aria-label',`${saved?'Unsave':'Save'} ${offers.find(p=>p.id===v).prize}`);if(route()==='/promotions'&&filters.status==='Saved')updateResults();toast(saved?'Promotion saved. Find it in Saved.':'Promotion removed from Saved.');return}if(b.dataset.status){filters.status=b.dataset.status;render();document.querySelector(`[data-status="${filters.status}"]`)?.focus({preventScroll:true});return}if(b.dataset.profile){profileTab=b.dataset.profile;if(route()!=='/profile'){location.hash='/profile'}else render();return}switch(b.dataset.action){case'menu':menuOpen=!menuOpen;$('.header').classList.toggle('menu-open',menuOpen);b.setAttribute('aria-expanded',String(menuOpen));b.innerHTML=icon(menuOpen?'close':'menu');break;case'toggle-auth':state.signed=!state.signed;persist();go('/');toast(state.signed?'Logged-in example enabled.':'Logged-out example enabled.');break;case'clear-filters':filters={q:'',brand:'All brands',type:'All types',status:'Available',sort:'recommended'};render();$('#search')?.focus();break;case'save-draft':entryDraft={...entryDraft,code:$('#entry-code')?.value,eligible:$('#eligible')?.checked,rules:$('#rules-agree')?.checked};break;case'reset-dialog':openDialog('Reset this example?',`<p>This clears your changes and restores the starter member, favourites and two illustrative entries on this browser.</p><div class="row"><button class="btn" data-action="reset">Reset example data</button><button class="btn secondary" data-action="close-dialog">Keep my changes</button></div>`);break;case'reset':state=structuredClone(seed);persist();entryDraft={};$('#dialog').close();render();toast('Starter example restored.');break;case'close-dialog':$('#dialog').close();break}});
$('#dialog').addEventListener('close',()=>{if(returnFocus?.isConnected)returnFocus.focus()});
document.addEventListener('input',e=>{if(e.target.id==='search'){filters.q=e.target.value;updateResults()}});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='country'){state.country=el.value;persist();render();toast('Example market changed to '+state.country)}else if(el.id==='brand-filter'){filters.brand=el.value;updateResults()}else if(el.id==='type-filter'){filters.type=el.value;updateResults()}else if(el.id==='availability'){filters.status=el.value;document.querySelectorAll('[data-status]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.status===filters.status)));updateResults()}else if(el.id==='sort'){filters.sort=el.value;updateResults()}});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target;if(f.id==='entry-form'){const p=offers.find(p=>p.id===f.dataset.id),code=$('#entry-code'),error=$('#form-error');error.textContent='';if(code){const valid=code.value.replace(/\s/g,'').toUpperCase()==='JOY2026';code.setAttribute('aria-invalid',String(!valid));$('#code-error').textContent=valid?'':'Use JOY2026 for this example. No real pack code is needed.';if(!valid){code.focus();return}}if(!$('#eligible').checked||!$('#rules-agree').checked){error.textContent='Please confirm both required statements before continuing.';(!$('#eligible').checked?$('#eligible'):$('#rules-agree')).focus();return}const outcome=$('#test-outcome').value,submit=f.querySelector('button[type=submit]');submit.disabled=true;submit.innerHTML='<span>Submitting example…</span>';f.setAttribute('aria-busy','true');await new Promise(resolve=>setTimeout(resolve,500));if(!f.isConnected)return;if(outcome==='error'){submit.disabled=false;submit.innerHTML='Try again '+icon('arrow');f.removeAttribute('aria-busy');error.textContent='The example connection failed. Your entry was not submitted. Your information is still here. Choose a result scenario and try again.';$('#test-outcome').value=p.type==='Instant win'?'loss':'draw';error.tabIndex=-1;error.focus();return}const existing=entry(p); if(existing&&entryDraft.replay===p.id){existing.outcome=outcome;existing.date='2026-10-16'}else if(!existing)state.entries.unshift({id:p.id,outcome,date:'2026-10-16',ref:'JOY-DEMO-'+(1003+state.entries.length)});persist();entryDraft={};go('/result/'+p.id)}else if(f.id==='join-form'){if(!$('#join-agree').checked){$('#join-error').textContent='Please acknowledge the simulation before continuing.';$('#join-agree').focus();return}state.name=$('#demo-name').value.trim()||'Alex';state.country=$('#join-country').value;state.signed=true;persist();go(f.dataset.next?'/promotion/'+f.dataset.next:'/');toast('Welcome to the example member experience.')}else if(f.id==='preferences-form'){state.notifications=$('#news-pref').checked;persist();toast('Example preferences saved. No email will be sent.')}else if(f.id==='personal-form'){state.name=$('#profile-name').value.trim()||'Alex';persist();render();toast('Example display name saved.')}});
window.addEventListener('hashchange',()=>{menuOpen=false;render();window.scrollTo(0,0);$('#main').focus({preventScroll:true})});
render();
